/**
 * src/institutional.ts — Institutional (staff) mode flag + staff case store.
 *
 * IRU has TWO MODES (owner correction 2026-11-11): consumer mode and
 * staff mode — two distinctive apps. The institutional version is built
 * OFF OF the DTC app: it inherits the DTC intelligence, form fills,
 * document uploads, and intelligence processing. It is NOT a separate
 * parallel/questionnaire-only Tier 1 build.
 *
 * Mode resolution (build time, never a runtime guess):
 *   1. VITE_IRU_MODE env var (explicit override).
 *   2. BUILD_MODE from src/build-mode.ts (generated by
 *      scripts/set-build-mode.mjs from VITE_IRU_MODE or the Vercel
 *      branch ref — the `institutional` branch resolves to institutional).
 *   3. Default 'consumer'.
 *
 * Staff case store (localStorage, this device only): the organization's
 * own system is the source of truth for cases; IRU is the intelligence
 * layer that works alongside it. The store tracks intake only —
 * participant, form, status, and when a report was last sent. It never
 * holds the applicant's answers (those stay in the per-form Tier 1
 * autosave, iru_tier1_<formKey>). One active case per form per device:
 * Tier 1 autosave is keyed by form, so two participants on the same
 * form on the same device share that autosave slot — a known limit,
 * noted for the accounts/server-case-storage step.
 */

import { BUILD_MODE } from './build-mode';

export function INSTITUTIONAL_MODE(): boolean {
  try {
    const env = (import.meta as any).env;
    if (env && typeof env.VITE_IRU_MODE === 'string' && env.VITE_IRU_MODE) {
      return env.VITE_IRU_MODE === 'institutional';
    }
  } catch {
    /* ignore — fall through to the generated build mode */
  }
  return BUILD_MODE === 'institutional';
}

export const STAFF_FORM_KEYS = ['n400', 'i130', 'i485', 'i90', 'i589', 'i765'] as const;
export type StaffFormKey = (typeof STAFF_FORM_KEYS)[number];

export const STAFF_FORM_LABELS: Record<string, string> = {
  n400: 'N-400 — Become a U.S. Citizen',
  i130: 'I-130 — Petition for a Family Member',
  i485: 'I-485 — Apply for a Green Card',
  i90: 'I-90 — Renew or Replace My Green Card',
  i589: 'I-589 — Apply for Asylum',
  i765: 'I-765 — Apply for a Work Permit',
};

export const STAFF_FORM_NUMBERS: Record<string, string> = {
  n400: 'N-400',
  i130: 'I-130',
  i485: 'I-485',
  i90: 'I-90',
  i589: 'I-589',
  i765: 'I-765',
};

export type StaffCaseStatus = 'intake' | 'in-review' | 'ready' | 'filed';

export interface StaffCase {
  id: string;
  participantName: string;
  formKey: string;
  status: StaffCaseStatus;
  createdAt: number;
  updatedAt: number;
  lastSentAt?: number;
  lastSentTo?: string;
}

const STAFF_CASES_KEY = 'iru_staff_cases';

function staffStoreGet(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function staffStoreSet(key: string, value: string): void {
  try {
    localStorage.setItem(key, value);
  } catch {
    /* storage full or unavailable — intake continues without persistence */
  }
}

export function listStaffCases(): StaffCase[] {
  try {
    const raw = staffStoreGet(STAFF_CASES_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((c: any) => c && typeof c.id === 'string' && typeof c.formKey === 'string')
      .sort((a: any, b: any) => (b.updatedAt || 0) - (a.updatedAt || 0));
  } catch {
    return [];
  }
}

function writeStaffCases(cases: StaffCase[]): void {
  staffStoreSet(STAFF_CASES_KEY, JSON.stringify(cases));
}

export function createStaffCase(participantName: string, formKey: string): StaffCase {
  const now = Date.now();
  const c: StaffCase = {
    id: `case_${now.toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
    participantName: (participantName || '').trim(),
    formKey,
    status: 'intake',
    createdAt: now,
    updatedAt: now,
  };
  const cases = listStaffCases();
  cases.unshift(c);
  writeStaffCases(cases);
  return c;
}

export function getStaffCase(id: string): StaffCase | null {
  return listStaffCases().find((c) => c.id === id) || null;
}

export function updateStaffCase(id: string, patch: Partial<StaffCase>): StaffCase | null {
  const cases = listStaffCases();
  const idx = cases.findIndex((c) => c.id === id);
  if (idx < 0) return null;
  const next = { ...cases[idx], ...patch, updatedAt: Date.now() };
  cases[idx] = next;
  writeStaffCases(cases);
  return next;
}

export function markCaseReportSent(id: string, staffEmail: string): StaffCase | null {
  return updateStaffCase(id, { lastSentAt: Date.now(), lastSentTo: staffEmail });
}

// ── Per-organization staff receiving setup ─────────────────────────────
// CORRECTED MODEL (owner, 2026-11-11): there are TWO kinds of consumer —
// the CORPORATE consumer (the organization, e.g. BronxWorks, which has a
// staff version) and the PERSONAL direct-to-consumer (the individual
// buying IRU directly). The staff version CONNECTS WITH the consumer
// module: a consumer completes their case in the consumer module and it
// routes to that organization's staff. Each org's staff has their OWN
// receiving setup (email), configured per organization — never a single
// hardcoded address, and the consumer never enters a staff email and
// never opens a mail app.
//
// How the staff email is configured per organization (two layers):
//   1. DEVICE (this layer, works now): staff configures their org's
//      receiving email once in the Staff Dashboard ("Staff receiving
//      setup"). It is stored on the device and the consumer module on
//      that device routes to it. Each org's staff sets their own.
//   2. SERVER (upgrade path): api/org-staff.json maps org slugs to staff
//      emails. When an org is in that registry, /api/send-report
//      resolves it server-side (authoritative — the client cannot
//      choose the recipient). The owner populates it with real staff
//      emails; it ships empty because no real staff email has been
//      provided and none is invented here.
// The org is identified by a URL `?org=<slug>` when the consumer arrives
// via an org link (their own phone), else by the device org config
// (a staff terminal / staff-started case).
export interface OrgConfig {
  orgSlug: string;
  orgName: string;
  staffEmail: string;
}

const ORG_CONFIG_KEY = 'iru_org_config';

export function slugifyOrg(name: string): string {
  return (name || '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64);
}

export function getOrgConfig(): OrgConfig | null {
  try {
    const raw = staffStoreGet(ORG_CONFIG_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed.staffEmail !== 'string' || !parsed.staffEmail.includes('@')) return null;
    return {
      orgSlug: typeof parsed.orgSlug === 'string' && parsed.orgSlug ? parsed.orgSlug : slugifyOrg(parsed.orgName || 'organization'),
      orgName: typeof parsed.orgName === 'string' ? parsed.orgName : 'Your organization',
      staffEmail: parsed.staffEmail,
    };
  } catch {
    return null;
  }
}

export function saveOrgConfig(orgName: string, staffEmail: string): OrgConfig | null {
  const name = (orgName || '').trim();
  const email = (staffEmail || '').trim();
  if (!email.includes('@')) return null;
  const cfg: OrgConfig = { orgSlug: slugifyOrg(name) || 'organization', orgName: name || 'Your organization', staffEmail: email };
  staffStoreSet(ORG_CONFIG_KEY, JSON.stringify(cfg));
  return cfg;
}

/** Org slug for this session: URL `?org=` wins, else the device config. */
export function resolveOrgSlug(): string | null {
  try {
    const params = new URLSearchParams(window.location.search);
    const fromUrl = (params.get('org') || '').trim().toLowerCase();
    if (fromUrl) return fromUrl;
  } catch {
    /* ignore */
  }
  const cfg = getOrgConfig();
  return cfg ? cfg.orgSlug : null;
}

// ── Testing vs install ─────────────────────────────────────────────────
// TESTING (now): the staff email is the owner's
// healthcarebyvalentine@gmail.com. All test sends go there — this also
// matches Resend's test-mode constraint (it only delivers to that
// address anyway). AT SALE/INSTALL (later, NOT now): when an organization
// buys and the app is installed for them, the owner creates an account
// for that org — that is when their own staff email / receiving setup
// is configured. Do NOT configure a real org staff address during
// testing. The per-org account creation is a sale/install-time step the
// owner does, not part of this build.
export const TEST_STAFF_EMAIL = 'healthcarebyvalentine@gmail.com';

export interface StaffDestination {
  orgSlug: string;
  orgName: string;
  staffEmail: string;
  isTestDefault: boolean;
}

/** The staff address a completed case routes to: the org's configured
 *  receiving email when staff set one, else the TEST default above. */
export function getStaffDestination(): StaffDestination {
  const cfg = getOrgConfig();
  if (cfg) {
    return { orgSlug: cfg.orgSlug, orgName: cfg.orgName, staffEmail: cfg.staffEmail, isTestDefault: false };
  }
  const slug = resolveOrgSlug();
  return {
    orgSlug: slug || 'test',
    orgName: slug ? slug : 'Test organization',
    staffEmail: TEST_STAFF_EMAIL,
    isTestDefault: true,
  };
}
